const ART='sharliz-art-1',CORE=['index.html','manifest.webmanifest','icons/icon-192.png'];
const artKey=u=>{const p=u.pathname.slice(u.pathname.indexOf('/art/')+1);return M[p]?u.origin+u.pathname+'?h='+M[p]:null};
// a missing art file is asked from the server with cache:'no-cache': the browser's HTTP cache (Pages: max-age=600) can still hold
// the picture from before a deploy, and those old bytes stored under the new hash would stay for good
const getArt=(c,k,u)=>fetch(u,{cache:'no-cache'}).then(x=>{if(x.ok&&x.status===200)c.put(k,x.clone());return x});
